// Fragment Shader - Packed Resize Nearest Neighbor
precision highp float;

// Uniforms
uniform sampler2D uPackedTexture;  // Packed source texture (width/2 x height/2)
uniform vec2 uOutputSize;          // Output resolution in pixels (e.g., vec2(1920.0, 1080.0))
