// Pack source texture data
function packTexture(sourceData, width, height) {
    const packedWidth = Math.ceil(width / 2);
    const packedHeight = Math.ceil(height / 2);
    const packedData = new Uint8Array(packedWidth * packedHeight * 4);

    for (let y = 0; y < height; y += 2) {
        for (let x = 0; x < width; x += 2) {
            const px = x / 2;
            const py = y / 2;
            const idx = (py * packedWidth + px) * 4;

            // Read 4 source pixels (assuming grayscale)
            const v00 = sourceData[y * width + x];
            const v10 = sourceData[y * width + Math.min(x + 1, width - 1)];
            const v01 = sourceData[Math.min(y + 1, height - 1) * width + x];
            const v11 = sourceData[Math.min(y + 1, height - 1) * width + Math.min(x + 1, width - 1)];

            packedData[idx] = v00;
            packedData[idx + 1] = v10;
            packedData[idx + 2] = v01;
            packedData[idx + 3] = v11;
        }
    }
    return { data: packedData, width: packedWidth, height: packedHeight };
}

